sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({ api, event, helpers, imports }) {
  // Map record-list events → CRUD type
  const TYPE_MAP = {
    "NOW_RECORD_LIST_CONNECTED#SAVE_AS_REQUESTED": "CREATE",
    "NOW_RECORD_LIST_CONNECTED#DELETE_REQUESTED": "DESTROY",
    "NOW_RECORD_LIST_CONNECTED#RENAME_REQUESTED": "UPDATE",
    "NOW_RECORD_LIST_CONNECTED#EDIT_COLUMNS_REQUESTED": "UPDATE",
    "NOW_RECORD_LIST_CONNECTED#SAVE_REQUESTED": "UPDATE",
  };

  const type = TYPE_MAP[event?.name] || "";
  const payload = event?.payload || {};

  // Some events put details under payload.update; others don't.
  const options = payload.update ?? payload;

  const CRUD = {
    type,
    options,
    timestamp: payload.timestamp ?? Date.now(),
  };

  api.setState("CRUD", CRUD);

  // (Optional) show a toast so you can see it fire during wiring/testing
  if (type && helpers?.showToast) {
    helpers.showToast({ status: "info", content: `List ${type.toLowerCase()} requested` });
  }
}
